        validate(value) {
          return value.trim() ? "" : "Full name is required.";
        }
      },
      {
        id: "email",
        label: "Email address",
        type: "email",
        autocomplete: "email",
        placeholder: "alex@example.com",
        required: true,
        validate(value) {
          if (!value.trim()) {
            return "Email address is required.";
          }

          return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())
            ? ""
            : "Enter a valid email address.";
        }
      },
      {
        id: "phone",
        label: "Phone number",
        type: "tel",
        autocomplete: "tel",
        placeholder: "+1 555 123 4567",
        required: false,
        helperText: "Optional. Use an international format such as +1 555 123 4567.",
        validate(value) {
          if (!value.trim()) {
            return "";
          }

          return /^\+?[0-9\s().-]{7,20}$/.test(value.trim())
            ? ""
            : "Enter a phone number using digits, spaces, parentheses, periods, hyphens, and an optional leading plus sign.";
        }
      }
    ];

    const formState = Object.fromEntries(fields.map((field) => [field.id, ""]));
    const touchedState = Object.fromEntries(fields.map((field) => [field.id, false]));

    function SupportPage() {
      return `
        <section class="support-card" aria-labelledby="support-title">
          ${SupportHeader()}
          ${ContactForm()}
        </section>
      `;
    }

    function SupportHeader() {
      return `
        <header class="support-header">
          <p class="eyebrow">Support</p>
          <h1 id="support-title">How can we help?</h1>
          <p class="intro">Send our team your contact details and we will route your request to the right support specialist.</p>
        </header>
      `;
    }

    function ContactForm() {
      return `
        <form id="support-form" novalidate>
          ${fields.map(FormField).join("")}
          <div class="form-actions">
            <button type="submit">Contact support</button>
            <p class="status-message" id="form-status" role="status" aria-live="polite"></p>
          </div>
        </form>
      `;
    }

    function FormField(field) {
      const errorId = `${field.id}-error`;
      const helperId = `${field.id}-helper`;
      const describedBy = [field.helperText ? helperId : "", errorId].filter(Boolean).join(" ");

      return `
        <div class="form-field">
          <label for="${field.id}">
            ${field.label}${field.required ? ' <span class="required" aria-hidden="true">*</span>' : ""}
          </label>
          <input
            id="${field.id}"
            name="${field.id}"
