          touchedState[field.id] = true;
          validateField(field);
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        fields.forEach((field) => {
          touchedState[field.id] = true;
        });

        if (!validateForm()) {
          status.textContent = "";
          document.querySelector('[aria-invalid="true"]').focus();
