     function SupportHeader() {
       return `
         <header class="support-header">
           <p class="eyebrow">Support</p>
           <h1 id="support-title">How can we help?</h1>
           <p class="intro">Send our team your contact details and we will route your request to the right support specialist.</p>
         </header>
       `;
     }

     function ContactForm() {
       return `
         <form id="support-form" novalidate>
           ${fields.map(FormField).join("")}
           <div class="form-actions">
             <button type="submit">Contact support</button>
             <p class="status-message" id="form-status" role="status" aria-live="polite"></p>
           </div>
         </form>
       `;
     }

     function FormField(field) {
       const errorId = `${field.id}-error`;
       const helperId = `${field.id}-helper`;
       const describedBy = [field.helperText ? helperId : "", errorId].filter(Boolean).join(" ");

       return `
         <div class="form-field">
           <label for="${field.id}">
             ${field.label}${field.required ? ' <span class="required" aria-hidden="true">*</span>' : ""}
           </label>
           <input
             id="${field.id}"
             name="${field.id}"
             type="${field.type}"
             autocomplete="${field.autocomplete}"
             placeholder="${field.placeholder}"
             ${field.required ? "required" : ""}
             aria-invalid="false"
             aria-describedby="${describedBy}"
           >
           ${field.helperText ? `<p class="helper-text" id="${helperId}">${field.helperText}</p>` : ""}
           <p class="validation-message" id="${errorId}" aria-live="polite"></p>
         </div>
       `;
     }

     function validateField(field) {
       const input = document.getElementById(field.id);
       const message = field.validate(input.value);
       const error = document.getElementById(`${field.id}-error`);

       input.setAttribute("aria-invalid", message ? "true" : "false");
       error.textContent = message;
       return !message;
     }

     function validateForm() {
       return fields.map(validateField).every(Boolean);
     }

     function wireForm() {
       const form = document.getElementById("support-form");
       const status = document.getElementById("form-status");

       fields.forEach((field) => {
         const input = document.getElementById(field.id);

         input.addEventListener("input", (event) => {
           formState[field.id] = event.target.value;
           status.textContent = "";

           if (touchedState[field.id]) {
             validateField(field);
           }
         });

         input.addEventListener("blur", () => {
           touchedState[field.id] = true;
           validateField(field);
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         fields.forEach((field) => {
           touchedState[field.id] = true;
         });

         if (!validateForm()) {
           status.textContent = "";
           document.querySelector('[aria-invalid="true"]').focus();
           return;
         }

         status.textContent = "Thanks. Your support contact details are ready to send.";
         form.reset();
         fields.forEach((field) => {
           formState[field.id] = "";
           touchedState[field.id] = false;
           document.getElementById(field.id).setAttribute("aria-invalid", "false");
         });
       });
